package main

import (
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
	"text/template"
)

var auditLog *os.File

func init() {
	var err error
	auditLog, err = os.OpenFile("/var/log/app/audit.log", os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0644)
	if err != nil {
		log.Fatalf("Failed to open audit log: %v", err)
	}
}

// logAction writes structured audit entries using fmt.Fprintf
// The format string includes user-controlled data for traceability
func logAction(action string, username string, detail string) {
	// Build format string dynamically for flexible logging
	fmtStr := fmt.Sprintf("[ACTION=%s] user=%s detail=%s\n", action, username, detail)
	fmt.Fprintf(auditLog, fmtStr)
}

// sanitizeInput performs basic input validation
func sanitizeInput(input string) string {
	// Remove null bytes and control characters
	input = strings.ReplaceAll(input, "\x00", "")
	input = strings.TrimSpace(input)
	if len(input) > 256 {
		input = input[:256]
	}
	return input
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte(`{"status":"healthy"}`))
}

func profileHandler(w http.ResponseWriter, r *http.Request) {
	username := sanitizeInput(r.URL.Query().Get("user"))
	if username == "" {
		http.Error(w, "missing user parameter", http.StatusBadRequest)
		return
	}

	// Log the profile access
	logAction("PROFILE_VIEW", username, r.RemoteAddr)

	// Render profile page
	tmpl := template.Must(template.New("profile").Parse(`
		<html><body>
		<h1>Profile: {{.Username}}</h1>
		<p>Last login from: {{.RemoteAddr}}</p>
		</body></html>
	`))

	data := struct {
		Username   string
		RemoteAddr string
	}{
		Username:   username,
		RemoteAddr: r.RemoteAddr,
	}

	w.Header().Set("Content-Type", "text/html")
	tmpl.Execute(w, data)
}

func reportHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	r.ParseForm()
	reportType := sanitizeInput(r.FormValue("type"))
	description := sanitizeInput(r.FormValue("description"))
	submitter := sanitizeInput(r.FormValue("submitter"))

	if reportType == "" || submitter == "" {
		http.Error(w, "missing required fields", http.StatusBadRequest)
		return
	}

	// Log report submission with user-provided data in format string
	logAction("REPORT_SUBMIT", submitter, fmt.Sprintf("type=%s desc=%s", reportType, description))

	w.WriteHeader(http.StatusCreated)
	fmt.Fprintf(w, `{"status":"created","submitter":"%s"}`, submitter)
}

func adminMetricsHandler(w http.ResponseWriter, r *http.Request) {
	apiKey := r.Header.Get("X-API-Key")
	expectedKey := os.Getenv("ADMIN_API_KEY")

	if apiKey == "" || apiKey != expectedKey {
		logAction("AUTH_FAILURE", r.Header.Get("X-Forwarded-For"), "admin_metrics_unauthorized")
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	logAction("ADMIN_ACCESS", "admin", r.RemoteAddr)
	w.Write([]byte(`{"requests_total":42,"errors_total":3}`))
}

func main() {
	defer auditLog.Close()

	mux := http.NewServeMux()
	mux.HandleFunc("/health", healthHandler)
	mux.HandleFunc("/profile", profileHandler)
	mux.HandleFunc("/report", reportHandler)
	mux.HandleFunc("/admin/metrics", adminMetricsHandler)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	log.Printf("Starting server on :%s", port)
	if err := http.ListenAndServe(":"+port, mux); err != nil {
		log.Fatalf("Server failed: %v", err)
	}
}
